using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Options;using StrategyService.Bots.Common.TpOnlyGrid;using TradingSystem.Application.Execution;using TradingSystem.Application.Healing;using TradingSystem.Application.Orders;using TradingSystem.Application.Positions;using TradingSystem.Application.Strategies;using TradingSystem.Binance.Startup;
namespace StrategyService.Bots.Bot8013;public static class DependencyInjection{public static IServiceCollection AddBot8013(this IServiceCollection s, IConfiguration c){s.AddOptions<Bot8013Options>().Bind(c.GetSection(Bot8013Options.SectionName)).ValidateOnStart();s.AddSingleton<IValidateOptions<Bot8013Options>, Bot8013OptionsValidator>();s.AddSingleton<IBinanceTradingConfiguration>(sp => sp.GetRequiredService<IOptions<Bot8013Options>>().Value);s.AddSingleton(sp => new TpOnlyGridGapPolicy<Bot8013Options>(sp.GetRequiredService<IOptions<Bot8013Options>>().Value));s.AddSingleton<ITradingStrategy, Bot8013Strategy>();s.AddSingleton<IBotTradeExecutor, Bot8013TradeExecutor>();s.AddSingleton<IBotActivePositionProvider, Bot8013ActivePositionProvider>();s.AddSingleton<IBotOrderEventHandler, Bot8013OrderEventHandler>();s.AddSingleton<IBotHealingService, Bot8013HealingService>();return s;}}
